//
// Diagnostic-only alternative to rendering all pending glyph atlas outlines
// in their allocated, absolute page coordinates.
//
// For glifo's plain black outline sequences:
//    SetTransform(scaled real glyph), SetPaint(BLACK), FillPath(path)
// rasterize each *cache miss* at a glyph-local, integer-translation-free
// origin. Copy its finished coverage to the assigned atlas page rectangle
// using Vello's existing SrcOver/offset path. Cache-hit sampling remains
// Low/nearest and is not changed at all.
//
// NOT production ready. This path is intentionally slower on misses and
// must pass full fidelity + benchmark gates before any shipping equivalent.

use super::*;
use kurbo::Shape as _;

#[derive(Clone)]
struct LocalGlyph {
    path: Arc<BezPath>,
    transform: Affine,
    left: i32,
    top: i32,
    dst_x: u16,
    dst_y: u16,
    width: u16,
    height: u16,
}

const RASTER_PAD: i32 = 2;

fn local_glyph(
    transform: Affine,
    path: &Arc<BezPath>,
    page_width: u16,
    page_height: u16,
) -> Option<LocalGlyph> {
    let [a, b, c, d, tx, ty] = transform.as_coeffs();
    // glifo plain-outline cache misses have only uniform X and inverted-Y
    // scaling; preserve COLR/clipped/skewed commands on the original route.
    if !(a > 0.0 && d < 0.0 && b == 0.0 && c == 0.0)
        || !tx.is_finite() || !ty.is_finite()
    {
        return None;
    }
    let ix = tx.floor();
    let iy = ty.floor();
    // Crucial: floating point geometry/flattening sees only the stable
    // fractional phase. Integer atlas slot placement is applied AFTER
    // rasterization to the finished mask, not before coverage integration.
    let stable = Affine::new([a, b, c, d, tx - ix, ty - iy]);
    let bbox = stable.transform_rect_bbox(path.bounding_box());
    let wanted_left = bbox.x0.floor() - f64::from(RASTER_PAD);
    let wanted_top = bbox.y0.floor() - f64::from(RASTER_PAD);
    let wanted_right = bbox.x1.ceil() + f64::from(RASTER_PAD);
    let wanted_bottom = bbox.y1.ceil() + f64::from(RASTER_PAD);
    if ![wanted_left, wanted_top, wanted_right, wanted_bottom]
        .into_iter()
        .all(f64::is_finite)
    {
        return None;
    }

    // The legacy experiment rejected an entire atlas page replay whenever
    // the *extra two-pixel padding* crossed the page edge, even if the glyph
    // itself was valid inside the allocated slot. In the first ABBA, this was
    // the only reason for all 457 fallbacks. Clip the local staging window
    // to the destination atlas page rather than rejecting a whole batch.
    // The transform is still derived from the integer-translation-free
    // outline; no absolute page coordinate reaches the raster geometry.
    let left = wanted_left.max(-ix);
    let top = wanted_top.max(-iy);
    let right = wanted_right.min(f64::from(page_width) - ix);
    let bottom = wanted_bottom.min(f64::from(page_height) - iy);
    let (w, h) = (right - left, bottom - top);
    let (dst_x, dst_y) = (ix + left, iy + top);
    if !(1.0..=256.0).contains(&w)
        || !(1.0..=256.0).contains(&h)
        || dst_x < 0.0 || dst_y < 0.0
        || dst_x + w > f64::from(page_width)
        || dst_y + h > f64::from(page_height)
    {
        return None;
    }
    let transform = Affine::translate((-left, -top)) * stable;
    Some(LocalGlyph {
        path: Arc::clone(path),
        transform,
        left: left as i32,
        top: top as i32,
        dst_x: dst_x as u16,
        dst_y: dst_y as u16,
        width: w as u16,
        height: h as u16,
    })
}

pub(super) fn replay(
    commands: &mut Vec<AtlasCommand>,
    glyph_renderer: &mut RenderContext,
    page: &mut Pixmap,
    page_index: u32,
) -> bool {
    if std::env::var_os("AQ_TEST_CANONICAL_OUTLINE_REPLAY").is_none() {
        return false;
    }

    // Do not touch COLR/bitmap/clip/mixed commands in this first experiment.
    // Plain outlines generated by glifo::render_outline_to_atlas form
    // consecutive triples. Validate the whole batch *before* any write.
    if commands.is_empty() || commands.len() % 3 != 0 {
        std::eprintln!(
            "VELLO_CANONICAL_OUTLINE fallback=nontriple page={page_index} count={}",
            commands.len()
        );
        return false;
    }

    let mut glyphs = Vec::new();
    for triple in commands.chunks_exact(3) {
        let [
            AtlasCommand::SetTransform(t),
            AtlasCommand::SetPaint(_paint),
            AtlasCommand::FillPath(path),
        ] = triple else {
            std::eprintln!("VELLO_CANONICAL_OUTLINE fallback=mixed page={page_index}");
            return false;
        };
        let Some(local) = local_glyph(*t, path, page.width(), page.height()) else {
            std::eprintln!("VELLO_CANONICAL_OUTLINE fallback=bounds page={page_index}");
            return false;
        };
        glyphs.push(local);
    }

    for glyph in &glyphs {
        glyph_renderer.reset_and_resize(glyph.width, glyph.height);
        glyph_renderer.set_transform(glyph.transform);
        glyph_renderer.set_paint(BLACK);
        glyph_renderer.fill_path(&glyph.path);
        glyph_renderer.flush();
        glyph_renderer.render_with(
            &mut *page,
            &mut Resources::default(),
            RasterizerSettings {
                target_init: TargetInit::SrcOver,
                offset: (glyph.dst_x, glyph.dst_y),
                ..Default::default()
            },
        );
    }
    std::eprintln!(
        "VELLO_CANONICAL_OUTLINE applied page={page_index} count={}          first={:?}",
        glyphs.len(),
        glyphs.first().map(|g| (g.left, g.top, g.dst_x, g.dst_y)),
    );
    commands.clear();
    true
}
